CREATE TABLE public.sale_invoice_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), store_id uuid NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE, sale_id uuid NOT NULL REFERENCES public.sales(id) ON DELETE CASCADE, path text NOT NULL UNIQUE, filename text NOT NULL, kind text NOT NULL CHECK (kind IN ('pdf','xml')), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.sale_invoice_files TO authenticated;
GRANT ALL ON public.sale_invoice_files TO service_role;
ALTER TABLE public.sale_invoice_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY "document viewers read invoices" ON public.sale_invoice_files FOR SELECT TO authenticated USING (public.has_store_permission(store_id,'view_contracts'));
CREATE POLICY "document viewers attach invoices" ON public.sale_invoice_files FOR INSERT TO authenticated WITH CHECK (public.has_store_permission(store_id,'view_contracts') AND created_by=auth.uid());
CREATE FUNCTION public.invoice_file_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.sales s WHERE s.id=NEW.sale_id AND s.store_id=NEW.store_id) THEN RAISE EXCEPTION 'Venda não pertence à loja.'; END IF; IF NEW.path NOT LIKE NEW.store_id::text || '/invoices/' || NEW.sale_id::text || '/%' OR right(NEW.path,length(NEW.kind)+1)<>'.'||NEW.kind THEN RAISE EXCEPTION 'Arquivo não pertence à venda.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER invoice_file_guard BEFORE INSERT ON public.sale_invoice_files FOR EACH ROW EXECUTE FUNCTION public.invoice_file_guard();
CREATE POLICY "document viewers upload invoices" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='store-files' AND (storage.foldername(name))[2]='invoices' AND public.has_store_permission(public.safe_uuid((storage.foldername(name))[1]),'view_contracts') AND EXISTS (SELECT 1 FROM public.sales s WHERE s.id=public.safe_uuid((storage.foldername(name))[3]) AND s.store_id=public.safe_uuid((storage.foldername(name))[1])));
CREATE POLICY "document viewers remove orphan invoices" ON storage.objects FOR DELETE TO authenticated USING (bucket_id='store-files' AND (storage.foldername(name))[2]='invoices' AND public.has_store_permission(public.safe_uuid((storage.foldername(name))[1]),'view_contracts') AND NOT EXISTS (SELECT 1 FROM public.sale_invoice_files f WHERE f.path=name));